abstract final class EnglishAdvancedA2FinalSixSeven {static const lessons=<EnglishAdvancedLesson>[
EnglishAdvancedLesson(level:'A2',number:6,unitNumber:1,title:"Missing the Last Bus",titleArabic:"فوات الحافلة الأخيرة",storyTitle:"Missing the Last Bus",storyTitleArabic:"فوات الحافلة الأخيرة",paragraphs:<String>["After her evening class, Mina arrived at the bus stop. A digital display showed that the last service had gone. She checked the route map, but no other buses were available. Her phone battery was low and she was worried about getting home safely.","Mina entered a café and asked a waiter for help. He suggested a shared taxi with a licensed driver. She contacted her sister and waited inside until the car arrived. Before leaving, she checked the fare with the driver.","The journey home was calm. The following morning Mina set a reminder and downloaded a new timetable. She planned to leave class earlier the following Thursday. A difficult trip had taught her how to prepare a backup travel plan."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("bus stop","موقف حافلات"),EnglishAdvancedWord("digital display","شاشة رقمية"),EnglishAdvancedWord("service","خدمة نقل"),EnglishAdvancedWord("route map","خريطة المسار"),EnglishAdvancedWord("phone battery","بطارية الهاتف"),EnglishAdvancedWord("café","مقهى"),EnglishAdvancedWord("waiter","نادل"),EnglishAdvancedWord("shared taxi","سيارة أجرة مشتركة"),EnglishAdvancedWord("licensed driver","سائق مرخص"),EnglishAdvancedWord("reminder","تذكير")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("night route","خط ليلي"),EnglishAdvancedWord("transport app","تطبيق نقل"),EnglishAdvancedWord("fare estimate","تقدير الأجرة"),EnglishAdvancedWord("safe pickup","نقطة ركوب آمنة"),EnglishAdvancedWord("journey planner","مخطط رحلات"),EnglishAdvancedWord("travel alert","تنبيه سفر"),EnglishAdvancedWord("charging point","منفذ شحن"),EnglishAdvancedWord("customer helpline","رقم مساعدة"),EnglishAdvancedWord("travel card","بطاقة مواصلات"),EnglishAdvancedWord("rush hour","ساعة الذروة"),EnglishAdvancedWord("late arrival","وصول متأخر"),EnglishAdvancedWord("meeting point","نقطة التقاء"),EnglishAdvancedWord("time limit","مهلة زمنية"),EnglishAdvancedWord("backup transport","نقل احتياطي")],grammarTitle:"Going to versus will",grammarArabic:"نستخدم be going to لخطة قررناها مسبقًا، مثل I am going to leave early. ونستخدم will لقرار نتخذه الآن: I will call a taxi. وبعد will يأتي الفعل الأساسي.",grammarExamples:<String>["I am going to check the timetable.","The bus is gone, so I will call my sister.","Are you going to travel tomorrow?"],listening:"Attention passengers. The final bus from Central Square left at nine forty-five. There will be no replacement service tonight. For advice about other transport, call our customer helpline. Starting next Monday, the last bus will leave fifteen minutes later. Please check the updated timetable before planning your journey.",listeningQuestion:"What changes on Monday?",listeningOptions:<String>["The last bus leaves later","Tickets become free","The stop closes"],listeningAnswer:0,readingQuestion:"Where did Mina wait for her car?",readingOptions:<String>["Inside a café","At school","At the empty bus stop"],readingAnswer:0,writingCue:"Mina set a ____ on her phone.",writingAnswer:"reminder"),
EnglishAdvancedLesson(level:'A2',number:7,unitNumber:1,title:"A New Classmate",titleArabic:"زميلة جديدة",storyTitle:"A New Classmate",storyTitleArabic:"زميلة جديدة",paragraphs:<String>["Hana joined Leo's language class on Monday. The teacher asked everyone to introduce themselves and complete a group exercise. Hana liked drawing, but she was nervous because she did not know anyone at the school.","Leo invited Hana to the art club. They walked along the corridor and spoke about their favorite subjects. He showed her a poster for the coming school concert and explained that new students were welcome.","Hana enjoyed sketching another poster with the other members. By the end of the afternoon, she had met friendly students and felt confident. She thanked Leo for being kind and promised to come back next week."],storyWords:<EnglishAdvancedWord>[EnglishAdvancedWord("language class","حصة لغة"),EnglishAdvancedWord("introduce","يعرّف"),EnglishAdvancedWord("group exercise","نشاط جماعي"),EnglishAdvancedWord("drawing","رسم"),EnglishAdvancedWord("art club","نادي فنون"),EnglishAdvancedWord("corridor","ممر"),EnglishAdvancedWord("favorite subjects","مواد مفضلة"),EnglishAdvancedWord("poster","ملصق"),EnglishAdvancedWord("school concert","حفل مدرسي"),EnglishAdvancedWord("sketching","رسم تخطيطي")],extraWords:<EnglishAdvancedWord>[EnglishAdvancedWord("school timetable","جدول مدرسي"),EnglishAdvancedWord("study partner","شريك دراسة"),EnglishAdvancedWord("school counselor","مرشد طلابي"),EnglishAdvancedWord("classroom rules","قواعد الصف"),EnglishAdvancedWord("homework folder","ملف الواجبات"),EnglishAdvancedWord("language exchange","تبادل لغوي"),EnglishAdvancedWord("discussion group","مجموعة نقاش"),EnglishAdvancedWord("creative project","مشروع فني"),EnglishAdvancedWord("pencil case","مقلمة"),EnglishAdvancedWord("school noticeboard","لوحة الإعلانات"),EnglishAdvancedWord("first impression","انطباع أول"),EnglishAdvancedWord("team activity","نشاط فريق"),EnglishAdvancedWord("after-school club","نادي بعد الدوام"),EnglishAdvancedWord("school trip","رحلة مدرسية")],grammarTitle:"Present perfect: ever and never",grammarArabic:"نستخدم have أو has مع التصريف الثالث للتحدث عن خبراتنا: Have you ever joined a club? وShe has never been there. لكن مع وقت مثل yesterday نستخدم الماضي البسيط.",grammarExamples:<String>["Have you ever joined a club?","She has never made a poster before.","I visited that classroom yesterday."],listening:"Welcome to the school's art club. We meet every Wednesday after the last class in Room Twelve. Beginners are welcome and no special experience is needed. Please bring pencils and paper. This term we are creating posters for the spring concert. Senior students will help new members with every activity.",listeningQuestion:"Who can join the club?",listeningOptions:<String>["Only experienced artists","Interested beginners","Only teachers"],listeningAnswer:1,readingQuestion:"Why did Leo invite Hana?",readingOptions:<String>["She liked drawing","She missed a bus","She lost her bag"],readingAnswer:0,writingCue:"Hana created a colorful ____.",writingAnswer:"poster"),
];}
